SELECT COUNT(*) AS hyundai_vehicle_count
FROM vehicles
WHERE make = 'Hyundai';

SELECT COUNT(*) AS inactive_user_count
FROM users
WHERE is_active = false;

SELECT COUNT(*) AS in_progress_ride_count
FROM rides
WHERE status = 'in_progress';

SELECT COUNT(*) AS completed_rides_over_100
FROM rides
WHERE status = 'completed' AND fare > 100;

SELECT COUNT(*) AS ratings_with_comment
FROM ratings
WHERE comment IS NOT NULL;

SELECT COUNT(*) AS user_accounts_created
FROM users
WHERE signup_date BETWEEN '2025-01-01' AND '2025-06-30';

SELECT COUNT(*) AS drivers_with_zero_ratings
FROM users u
WHERE u.user_type = 'driver'
  AND NOT EXISTS (
    SELECT 1 FROM ratings r WHERE r.driver_id = u.user_id
  );

SELECT AVG(rating_count) AS avg_ratings_per_driver
FROM (
    SELECT driver_id, COUNT(*) AS rating_count
    FROM ratings
    GROUP BY driver_id
) AS driver_ratings;
